        // 2. Disc authoring ComboBox legibility (label text contrasts strongly against box fill)
        auto verifyComboBoxSnapshot = [&](juce::ComboBox& box, const char* name) {
            box.resized();
            const auto w = box.getWidth();
            const auto h = box.getHeight();
            const auto visMsg =
                juce::String(name) + " is visible with a selected option and valid bounds";
            check(w > 40 && h > 16 && box.isVisible() && box.getSelectedId() > 0,
                  visMsg.toRawUTF8());
            const auto snap = box.createComponentSnapshot(box.getLocalBounds());
            const auto bgPx = snap.getPixelAt(2, h / 2);
            bool foundInk = false;
            for (int px = 7; px < w - 25 && !foundInk; ++px) {
                for (int py = 3; py < h - 3; ++py) {
                    const auto c = snap.getPixelAt(px, py);
                    if (std::abs(static_cast<int>(c.getRed()) - static_cast<int>(bgPx.getRed())) >=
                        60) {
                        foundInk = true;
                        break;
                    }
                }
            }
            const auto inkMsg =
                juce::String(name) + " renders legible contrasting option text inside label area";
            check(foundInk, inkMsg.toRawUTF8());
        };
        verifyComboBoxSnapshot(dock.mediumBox, "Medium ComboBox");
        verifyComboBoxSnapshot(dock.codecBox, "Codec ComboBox");

