            restored.selectRows({0, 2});
            check(restored.list.getNumSelectedRows() == 2 && restored.list.isRowSelected(0) &&
                      restored.list.isRowSelected(2) && restored.shift.isEnabled(),
                  "marker-list reopening restores the shifted nonadjacent selection");
