            studio.session.tracks[0].gain = 0.73123455f;
            studio.session.tracks[0].clips[0].gain = 0.73123455f;
            studio.session.tracks[0].clips[0].fadeIn = 0.123456789;
            studio.selectedTrack = studio.selectedClip = 0;
            studio.editHistory.reset();
            studio.dirty = false;
