                audio->samples.setSample(0, i, 0.25f);
            studio.session = {};
            studio.session.tracks.push_back({"One", {{audio, 10 / rate, 0, 50 / rate}}});
            studio.session.tracks.push_back({"Other", {{audio, 30 / rate, 0, 40 / rate}}});
            studio.session.tracks.push_back({"Three", {{audio, 200 / rate, 0, 50 / rate}}});
            studio.editHistory.reset();
            studio.selectedTrack = 0;
            studio.selectedClip = 0;
