            const double neighborPosition = static_cast<double>(neighborSample) / rate;
            studio.session.markers = {{3, "First"}, {neighborPosition, "Neighbor"}};
            studio.editHistory.reset();
            studio.selectedMarker = 0;
            const int neighborX = studio.timeToX(neighborPosition);
