            studio.deviceRate = 0;
            studio.session = {};
            studio.timeSelection = {};
            studio.selectedTrack = studio.selectedClip = -1;
            studio.playbackIndex.reset();
            studio.masterRangeValid = false;
            studio.playbackClock.reset();
            studio.dirty = false;
