            studio.nudgeClipGroup(1);
            check(studio.timelineClipSelection.contains(1, 0, studio.editGeneration) &&
                      studio.timelineClipSelection.contains(2, 1, studio.editGeneration),
                  "exactly moved group remains selected for repeated nudges");
            studio.restoreHistory(false);
            studio.restoreHistory(false);
            check(studio.session.tracks[0].clips[0].name == "From A" &&
                      studio.session.tracks[1].clips[0].name == "From B",
                  "undo restores an exact group move and subsequent nudge");
            reset();
            studio.timelineClipSelection.toggle(studio.session, {1, 0}, studio.editGeneration);
            studio.performTimelineClipAction(191);
            check(studio.session.tracks[0].clips.size() == 2 &&
                      studio.session.tracks[1].clips.size() == 2 &&
                      studio.timelineClipSelection.contains(0, 1, studio.editGeneration) &&
                      studio.timelineClipSelection.contains(1, 1, studio.editGeneration) &&
                      !studio.timelineClipSelection.contains(0, 0, studio.editGeneration) &&
                      studio.selectedTrack == 0 && studio.selectedClip == 1 &&
                      studio.timeSelection.start == 44100,
                  "duplicating a clip group selects the new copies, keeps anchor focus and retains "
                  "the time range");
            const auto duplicateStart = studio.session.tracks[0].clips[1].start;
            studio.nudgeClipGroup(1);
            check(studio.session.tracks[0].clips[1].start > duplicateStart &&
                      studio.timelineClipSelection.contains(1, 1, studio.editGeneration),
                  "the newly duplicated group can be nudged without reselecting");
            studio.restoreHistory(false);
